  "lib/org/experiment-prereg.js": {
    "path": "/home/beijong/.dsh/bot-workspaces/exp17-bare-research/lib/org/experiment-prereg.js",
    "offset": 1,
    "lines": [
      {
        "number": 1,
        "text": "/**"
      },
      {
        "number": 2,
        "text": " * 放大验收实验的预登记件机械面（org-v2 17 号票；规格 §J「放大验证实验设计」、"
      },
      {
        "number": 3,
        "text": " * 附录 A B 组 `V-B1`／`V-B2` 与「预登记件（实验前冻结，跑完不得改）」节）。"
      },
      {
        "number": 4,
        "text": " *"
      },
      {
        "number": 5,
        "text": " * 本模块只把守**预登记件**这一件事：基准集（3–5 个任务按放大机制各取一、每任务"
      },
      {
        "number": 6,
        "text": " * 四要素简报＋可执行 acceptance）、对照口径（裸实例＝同模型、同基础工具面、"
      },
      {
        "number": 7,
        "text": " * 无组织命令 op、无组织层脚手架、预算同量级）、数值门槛与成本口径的形状，"
      },
      {
        "number": 8,
        "text": " * 以及**冻结摘要**与裸对照入集判定。判据语义不在本模块（语义权威＝规格附录 A，"
      },
      {
        "number": 9,
        "text": " * 冻结）——故本件不是第二份判据清单，而是「实验前必须由用户预登记并随即冻结」"
      },
      {
        "number": 10,
        "text": " * 这条纪律的机械面。"
      },
      {
        "number": 11,
        "text": " *"
      },
      {
        "number": 12,
        "text": " * 数值门槛（绝对预算 B、量级倍数、重派封顶、初审与越权阈值——规格 §Testing"
      },
      {
        "number": 13,
        "text": " * Decisions 与「预登记件」节逐条点名）属**用户域**：本模块只判「填没填、是不是"
      },
      {
        "number": 14,
        "text": " * 正数、两臂预算是否同量级」，**不发明数值**。未填＝判缺口（`gaps`），非正数＝"
      },
      {
        "number": 15,
        "text": " * 违例（`violations`）；两条路都 `ok: false`（fail closed），冻结与判定都进不去。"
      },
      {
        "number": 16,
        "text": " *"
      },
      {
        "number": 17,
        "text": " * 对照口径按**命令面**切（规格 §J 价值表述括注「裸＝去组织层不去基础工具面」）："
      },
      {
        "number": 18,
        "text": " * 组织命令词表取 `lib/org/op-set.js` 的台账命令面（**单一源**，本模块不另抄"
      },
      {
        "number": 19,
        "text": " * 一份），裸侧一条都不许持；基础工具面（文件与执行工具）两臂须相同。"
      },
      {
        "number": 20,
        "text": " *"
      },
      {
        "number": 21,
        "text": " * 冻结＝对规范化 JSON 取 sha256：预登记件任何一字节改动都会换摘要，故「跑完"
      },
      {
        "number": 22,
        "text": " * 未改」可由摘要复验（`preregistrationUnchanged`）。入集判定（`admitBareSet`）"
      },
      {
        "number": 23,
        "text": " * 按 `V-B1`「裸对照先跑，失败方入集、裸跑成功即出集，不留在集里充数」——出集"
      },
      {
        "number": 24,
        "text": " * 带走的机制如实登记进 `mechanismsLost`（诊断事实），入集为空即无结论可出。"
      },
      {
        "number": 25,
        "text": " */"
      },
      {
        "number": 26,
        "text": "import { canonicalJson, sha256Hex } from \"./store-base.js\";"
      },
      {
        "number": 27,
        "text": "import { isPlainObject } from \"./capability-base.js\";"
      },
      {
        "number": 28,
        "text": "import { isTaskId } from \"./ledger-events.js\";"
      },
      {
        "number": 29,
        "text": "import { validateBrief } from \"./brief.js\";"
      },
      {
        "number": 30,
        "text": "import { LEDGER_COMMAND_OPS } from \"./op-set.js\";"
      },
