        "text": "  }"
      },
      {
        "number": 91,
        "text": "  const { tasks, events, artifacts = [], bareRuns = [] } = input;"
      },
      {
        "number": 92,
        "text": "  if (!Array.isArray(tasks)) violations.push(\"tasks（实验任务清单）须为数组\");"
      },
      {
        "number": 93,
        "text": "  if (!Array.isArray(events)) violations.push(\"events（台账事件序列）须为数组\");"
      },
      {
        "number": 94,
        "text": "  if (!Array.isArray(artifacts)) violations.push(\"artifacts（产出登记坐标）须为数组\");"
      },
      {
        "number": 95,
        "text": "  const causes = bareFailureCauses(bareRuns, violations);"
      },
      {
        "number": 96,
        "text": "  if (violations.length > 0) return { ok: false, tasks: [], violations };"
      },
      {
        "number": 97,
        "text": ""
      },
      {
        "number": 98,
        "text": "  const own = new Map(tasks.map((task) => [task.taskId, events.filter((event) => event?.taskId === task.taskId)]));"
      },
      {
        "number": 99,
        "text": "  const windows = new Map([...own].map(([taskId, list]) => [taskId, windowOf(list)]));"
      },
      {
        "number": 100,
        "text": "  const projected = tasks.map((task) => {"
