        "text": "    const list = own.get(task.taskId) ?? [];"
      },
      {
        "number": 102,
        "text": "    // 分解的腿落在**子任务自己的** intake 事件上（带 parentTaskId），不在本任务事件里"
      },
      {
        "number": 103,
        "text": "    const children = events"
      },
      {
        "number": 104,
        "text": "      .filter((event) => event?.type === DECOMPOSITION_EVENT && typeof event.parentTaskId === \"string\" && event.parentTaskId === task.taskId)"
