      {
        "number": 105,
        "text": "      .map((event) => event.taskId);"
      },
      {
        "number": 106,
        "text": "    const reviews = list.filter((event) => REVIEW_EVENT_TYPES.includes(event?.type)).length;"
      },
      {
        "number": 107,
        "text": "    const coordinates = [...new Set(["
      },
      {
        "number": 108,
        "text": "      ...list.filter((event) => event?.type === EXTERNALIZATION_EVENT && isNonEmptyString(event.deliverable)).map((event) => event.deliverable),"
      },
      {
        "number": 109,
        "text": "      ...artifacts.filter((entry) => entry?.taskId === task.taskId && typeof entry.location === \"string\").map((entry) => entry.location)"
      },
      {
        "number": 110,
        "text": "    ])];"
      },
      {
        "number": 111,
        "text": "    const overlapping = tasks"
      },
      {
        "number": 112,
        "text": "      .filter((other) => other.taskId !== task.taskId && overlaps(windows.get(task.taskId) ?? null, windows.get(other.taskId) ?? null))"
      },
      {
        "number": 113,
        "text": "      .map((other) => other.taskId)"
      },
      {
        "number": 114,
        "text": "      .sort();"
      },
      {
        "number": 115,
        "text": "    const mechanisms = {"
      },
      {
        "number": 116,
        "text": "      decomposition: children.length > 0,"
      },
      {
        "number": 117,
        "text": "      \"cross-check\": reviews > 0,"
      },
      {
        "number": 118,
        "text": "      externalization: coordinates.length > 0,"
      },
      {
        "number": 119,
        "text": "      parallel: overlapping.length > 0"
      },
      {
        "number": 120,
        "text": "    };"
      },
      {
        "number": 121,
        "text": "    return {"
      },
      {
        "number": 122,
        "text": "      taskId: task.taskId,"
      },
      {
        "number": 123,
        "text": "      mechanism: task.mechanism,"
      },
      {
        "number": 124,
        "text": "      mechanisms,"
      },
      {
        "number": 125,
        "text": "      appearances: ATTRIBUTION_MECHANISM_IDS.filter((id) => mechanisms[id]),"
      },
      {
        "number": 126,
        "text": "      evidence: {"
      },
      {
        "number": 127,
        "text": "        decomposition: { children },"
      },
      {
        "number": 128,
        "text": "        crossCheck: { reviews },"
      },
      {
        "number": 129,
        "text": "        externalization: { coordinates },"
      },
      {
        "number": 130,
        "text": "        parallel: { overlapping }"
