        "text": " *   - 边界要素可带结构化业务截止时间 `dueAt`（可选键，09 号票）：到期只由投递面"
      },
      {
        "number": 13,
        "text": " *     投影「已过期」供用户清理，不产生任何自动动作（`V-A5.3`）。"
      },
      {
        "number": 14,
        "text": " *"
      },
      {
        "number": 15,
        "text": " * **判据缺口**（规格 §B）：判据存在但不可执行，不是形状违规而是缺口——结论里"
      },
      {
        "number": 16,
        "text": " * 以 `gap = {kind: \"criteria-gap\", reason}` 单列，流程上须先分解为可观测项，"
      },
      {
        "number": 17,
        "text": " * 分解不出来标 `needs-user` 上浮（上浮动作属调用方工作流，本模块只给机械判定）。"
      },
      {
        "number": 18,
        "text": " * 结构违规（四要素缺失、键封闭破坏）走 `violations`，两条路都 `ok: false`"
      },
      {
        "number": 19,
        "text": " * （fail closed），但工作流含义不同——19 号票起台账边界对两者分拒绝码。"
      },
      {
        "number": 20,
        "text": " *"
      },
      {
        "number": 21,
        "text": " * **reviewPoints 省略口径（2026-09-19 用户裁定，19 号票⑥）**：整体省略或空数组"
      },
      {
        "number": 22,
        "text": " * ＝零必审交付的**合法**形态，是否登记复核点属派单方自觉（本模块不为其新增"
      },
      {
        "number": 23,
        "text": " * 结构违规）；必审集另有强制请求通道兜底（可加审不可免审），冻结后的复核点"
      },
      {
        "number": 24,
        "text": " * 删减由 `droppedReviewPoints` 判定、在台账 amend 通道拒绝。"
      },
      {
        "number": 25,
        "text": " *"
      },
      {
        "number": 26,
        "text": " * 校验点＝简报进入事实源的每一处（`task.intake`／`task.plan`／`task.amend`"
      },
      {
        "number": 27,
        "text": " * 的负载，`task.assign` 的冻结前置——见 lib/org/brief-gate.js）：派出即冻结，"
      },
      {
        "number": 28,
        "text": " * 冻结件必须是校验过的件。"
      },
      {
        "number": 29,
        "text": " *"
      },
      {
        "number": 30,
        "text": " * 原语单源（23 号票⑥）：`isNonEmptyString` 独立成件（`./is-non-empty-string.js`"
      },
      {
        "number": 31,
        "text": " * ——brief↔review-kit 循环 import 解环）；`isPlainObject` 取 capability-base"
      },
      {
        "number": 32,
        "text": " * 版（带原型校验，较本地旧版收紧——简报件在真实路径皆 JSON 解析或字面量构造，"
      },
      {
        "number": 33,
        "text": " * 等价域内；原型异常件将改判违规，23 号票面 Comments 在案）；判据 args 键校验"
      },
      {
        "number": 34,
        "text": " * 接 `argsMatchArgKeys`（probe.js 执行侧同口径谓词，免两处各留一份）。"
      },
      {
        "number": 35,
        "text": " */"
      },
      {
        "number": 36,
        "text": "import { PROBE_COMMAND_NAMES, argsMatchArgKeys, probeCommand } from \"./probe.js\";"
      },
      {
        "number": 37,
        "text": "import { REVIEW_BOUNDARY_IDS } from \"./review-kit.js\";"
      },
      {
        "number": 38,
        "text": "import { isPlainObject } from \"./capability-base.js\";"
      },
      {
        "number": 39,
        "text": "import { isNonEmptyString } from \"./is-non-empty-string.js\";"
      },
      {
        "number": 40,
        "text": ""
      },
      {
        "number": 41,
        "text": "/** 简报顶层键（封闭枚举；taskId／class／归属租约／父任务由台账任务对象持有，不入简报体）。"
      },
      {
        "number": 42,
        "text": " *  12 号票起导出于读面：恒久性面的岗位评测集记号从本枚举派生，不另抄一份（单源）。 */"
      },
      {
        "number": 43,
        "text": "export const BRIEF_KEYS = Object.freeze([\"goal\", \"deliverables\", \"sources\", \"boundaries\", \"acceptance\", \"reviewPoints\", \"dueAt\", \"promotion\"]);"
      },
      {
        "number": 44,
        "text": ""
      },
      {
        "number": 45,
        "text": "/**"
      },
      {
        "number": 46,
        "text": " * 冻结复核点删减判定（org-v2 19 号票①；规格 §C「可加审不可免审」在 amend 通道"
      },
      {
        "number": 47,
        "text": " * 的机械面——08 号票已在 review.request 通道把守降级请求，本判定守置换件）："
      },
      {
        "number": 48,
        "text": " * 返回置换件相对冻结件删掉的 reviewPoints（可归因到点）。**置换件省略该键＝视为"
      },
      {
        "number": 49,
        "text": " * 删全部**（免审不得经省略侧门兑现）；加审（新增点）不在删减列；冻结件无点或"
      },
      {
        "number": 50,
        "text": " * 不存在（intake 前置换）则无可删。reviewPoints 按**必审 subject 集合语义**判定"
      },
      {
        "number": 51,
        "text": " * （重复条目折叠为同一 subject，与 review-kit `collectReviewState` 同口径——"
      },
      {
        "number": 52,
        "text": " * 重复条目的增减不改变必审集，不构成删减）。"
      },
      {
        "number": 53,
        "text": " */"
      },
      {
        "number": 54,
        "text": "export function droppedReviewPoints(previousBrief, nextBrief) {"
      },
      {
        "number": 55,
        "text": "  const previous = Array.isArray(previousBrief?.reviewPoints) ? previousBrief.reviewPoints : [];"
      },
      {
        "number": 56,
        "text": "  const next = Array.isArray(nextBrief?.reviewPoints) ? nextBrief.reviewPoints : [];"
      },
      {
        "number": 57,
        "text": "  return previous.filter((point) => !next.includes(point));"
      },
      {
        "number": 58,
        "text": "}"
      },
      {
        "number": 59,
        "text": ""
      },
      {
        "number": 60,
        "text": "/**"
      },
      {
        "number": 61,
        "text": " * dueAt 可解析判定（非空字符串且 Date.parse 不为 NaN）——冻结期校验（本件）"
      },
      {
        "number": 62,
        "text": " * 与投递面到期投影（lib/org/human-inbox.js `isExpired`）共用的同一口径。"
      },
      {
        "number": 63,
        "text": " */"
      },
      {
        "number": 64,
        "text": "export function isParseableDueAt(value) {"
      },
      {
        "number": 65,
        "text": "  return isNonEmptyString(value) && !Number.isNaN(Date.parse(value));"
      },
      {
        "number": 66,
        "text": "}"
      },
      {
        "number": 67,
        "text": ""
      },
      {
        "number": 68,
        "text": "/** 坐标条目校验：键恰为 given（封闭），值全为非空字符串（坐标不是转述载体）。 */"
      },
      {
        "number": 69,
        "text": "function coordinateEntries(value, label, keys, violations) {"
      },
      {
        "number": 70,
        "text": "  if (!Array.isArray(value) || value.length === 0) {"
      },
      {
        "number": 71,
        "text": "    violations.push(`${label} 须为非空数组`);"
      },
      {
        "number": 72,
        "text": "    return;"
      },
      {
        "number": 73,
        "text": "  }"
      },
      {
        "number": 74,
        "text": "  value.forEach((entry, index) => {"
      },
      {
        "number": 75,
        "text": "    const at = `${label}[${String(index)}]`;"
      },
      {
        "number": 76,
        "text": "    if (!isPlainObject(entry)) {"
      },
      {
        "number": 77,
        "text": "      violations.push(`${at} 须为对象`);"
      },
      {
        "number": 78,
        "text": "      return;"
      },
      {
        "number": 79,
        "text": "    }"
      },
      {
        "number": 80,
        "text": "    for (const key of Object.keys(entry)) {"
      },
      {
        "number": 81,
        "text": "      if (!keys.includes(key)) violations.push(`${at} 含未定义键 ${key}（条目键封闭：${keys.join(\"/\")}，只给坐标不给转述）`);"
      },
      {
        "number": 82,
        "text": "    }"
      },
      {
        "number": 83,
        "text": "    for (const key of keys) {"
      },
      {
        "number": 84,
        "text": "      if (!isNonEmptyString(entry[key])) violations.push(`${at}.${key} 须为非空字符串`);"
      },
      {
        "number": 85,
        "text": "    }"
      },
      {
        "number": 86,
        "text": "  });"
      },
      {
        "number": 87,
        "text": "}"
      },
      {
        "number": 88,
        "text": ""
      },
      {
        "number": 89,
        "text": "/**"
      },
      {
        "number": 90,
        "text": " * 四要素简报校验（纯函数）。结论＝`{ok, violations, gap}`："
      },
      {
        "number": 91,
        "text": " * `violations`＝结构违例行数组（空数组＋`ok:true` 即合法）；`gap`＝判据缺口"
      },
      {
        "number": 92,
        "text": " * （`{kind:\"criteria-gap\", reason}` 或 null）。"
      },
      {
        "number": 93,
        "text": " */"
      },
      {
        "number": 94,
        "text": "export function validateBrief(brief) {"
      },
      {
        "number": 95,
        "text": "  const violations = [];"
      },
      {
        "number": 96,
        "text": "  if (!isPlainObject(brief)) {"
      },
      {
        "number": 97,
        "text": "    return { ok: false, violations: [\"简报须为对象（四要素固定形状）\"], gap: null };"
      },
      {
        "number": 98,
        "text": "  }"
      },
      {
        "number": 99,
        "text": "  for (const key of Object.keys(brief)) {"
      },
      {
        "number": 100,
        "text": "    if (!BRIEF_KEYS.includes(key)) violations.push(`简报含未定义键 ${key}（封闭键集：${BRIEF_KEYS.join(\"、\")}）`);"
      },
      {
        "number": 101,
        "text": "  }"
      },
      {
        "number": 102,
        "text": "  if (!isNonEmptyString(brief.goal)) violations.push(\"goal（目标）须为非空字符串\");"
      },
      {
        "number": 103,
        "text": "  coordinateEntries(brief.deliverables, \"deliverables（交付物）\", [\"format\", \"location\"], violations);"
      },
      {
        "number": 104,
        "text": "  coordinateEntries(brief.sources, \"sources（来源）\", [\"tool\", \"ref\"], violations);"
      },
      {
        "number": 105,
        "text": "  if (!isNonEmptyString(brief.boundaries)) violations.push(\"boundaries（边界）须为非空字符串\");"
      },
      {
        "number": 106,
        "text": "  if (brief.dueAt !== undefined) {"
      },
      {
        "number": 107,
        "text": "    // 边界要素的业务截止时间（09 号票）：结构化可选键，缺省＝无到期投影。"
      },
      {
        "number": 108,
        "text": "    // 到期只由投递面投影「已过期」供用户清理，不构成任何自动动作（V-A5.3）。"
      },
      {
        "number": 109,
        "text": "    if (!isParseableDueAt(brief.dueAt)) {"
      },
      {
        "number": 110,
        "text": "      violations.push(\"dueAt（业务截止时间）须为可解析的时间戳字符串（ISO 8601；缺省＝无到期投影）\");"
      },
      {
        "number": 111,
        "text": "    }"
      },
      {
        "number": 112,
        "text": "  }"
      },
      {
        "number": 113,
        "text": "  if (brief.promotion !== undefined) {"
      },
      {
        "number": 114,
        "text": "    // 晋升强制性预声明（10 号票，`V-A7.7`）：§G「强制性由派单方在简报输出格式里"
      },
      {
        "number": 115,
        "text": "    // 预声明（全局不设强制）」。结构形态＝封闭单键 `{required: boolean}`——`true`"
      },
      {
        "number": 116,
        "text": "    // ＝本单产出须在任务关闭/归档流程内走晋升登记，`false`＝不强制；缺省＝未声明"
      },
      {
        "number": 117,
        "text": "    // （与 false 同效但语义不同：缺省是「没提」，false 是「明示不强制」）。"
      },
      {
        "number": 118,
        "text": "    // 条目键封闭：不得把预声明做成语义决定的侧门（不预填 reused/supersedes id、"
      },
      {
        "number": 119,
        "text": "    // 不改产出方对内容的路由自决）。"
      },
      {
        "number": 120,
        "text": "    if (!isPlainObject(brief.promotion)) {"
      },
      {
        "number": 121,
        "text": "      violations.push(\"promotion（晋升预声明）须为 {required: boolean} 对象（缺省＝未声明）\");"
      },
      {
        "number": 122,
        "text": "    } else {"
      },
      {
        "number": 123,
        "text": "      for (const key of Object.keys(brief.promotion)) {"
      },
      {
        "number": 124,
        "text": "        if (key !== \"required\") violations.push(`promotion 含未定义键 ${key}（条目键封闭：required）`);"
      },
      {
        "number": 125,
        "text": "      }"
      },
      {
        "number": 126,
        "text": "      if (typeof brief.promotion.required !== \"boolean\") {"
      },
      {
        "number": 127,
        "text": "        violations.push(\"promotion.required 须为布尔量（true＝本单产出须走晋升登记）\");"
      },
      {
        "number": 128,
        "text": "      }"
      },
      {
        "number": 129,
        "text": "    }"
      },
      {
        "number": 130,
        "text": "  }"
      },
      {
        "number": 131,
        "text": "  if (brief.reviewPoints !== undefined) {"
      },
      {
        "number": 132,
        "text": "    // 复核点＝必审清单三判据的封闭枚举（08 号票）：枚举外字符串不得冻结进简报——"
      },
      {
        "number": 133,
        "text": "    // 免审与歧义都进不来（命中即强制的冻结期把守）"
      },
      {
        "number": 134,
        "text": "    if (!Array.isArray(brief.reviewPoints) || brief.reviewPoints.some((point) => !isNonEmptyString(point))) {"
      },
      {
        "number": 135,
        "text": "      violations.push(\"reviewPoints（复核点）须为非空字符串数组（可为空数组）\");"
      },
      {
        "number": 136,
        "text": "    } else {"
      },
      {
        "number": 137,
        "text": "      brief.reviewPoints.forEach((point, index) => {"
      },
      {
        "number": 138,
        "text": "        if (!REVIEW_BOUNDARY_IDS.includes(point)) {"
      },
      {
        "number": 139,
        "text": "          violations.push(`reviewPoints[${String(index)}] 不在必审清单边界枚举（${REVIEW_BOUNDARY_IDS.join(\"｜\")}）`);"
      },
      {
        "number": 140,
        "text": "        }"
      },
      {
        "number": 141,
        "text": "      });"
      },
      {
        "number": 142,
        "text": "    }"
      },
      {
        "number": 143,
        "text": "  }"
      },
      {
        "number": 144,
        "text": ""
      },
      {
        "number": 145,
        "text": "  // 验收判据：非空是结构不变量（violations）；「在但不可执行」是判据缺口（gap）。"
      },
      {
        "number": 146,
        "text": "  let gap = null;"
      },
      {
        "number": 147,
        "text": "  if (!Array.isArray(brief.acceptance) || brief.acceptance.length === 0) {"
      },
      {
        "number": 148,
        "text": "    violations.push(\"acceptance（验收判据）须为非空数组（判据非空不变量）\");"
      },
      {
        "number": 149,
        "text": "  } else {"
      },
      {
        "number": 150,
        "text": "    const unusable = [];"
      },
      {
        "number": 151,
        "text": "    brief.acceptance.forEach((entry, index) => {"
      },
      {
        "number": 152,
        "text": "      const at = `acceptance[${String(index)}]`;"
      },
      {
        "number": 153,
        "text": "      if (!isPlainObject(entry)) {"
      },
      {
        "number": 154,
        "text": "        unusable.push(`${at} 须为 {probe, args} 对象`);"
      },
      {
        "number": 155,
        "text": "        return;"
      },
      {
        "number": 156,
        "text": "      }"
      },
      {
        "number": 157,
        "text": "      for (const key of Object.keys(entry)) {"
      },
      {
        "number": 158,
        "text": "        if (key !== \"probe\" && key !== \"args\") unusable.push(`${at} 含未定义键 ${key}`);"
      },
      {
        "number": 159,
        "text": "      }"
      },
      {
        "number": 160,
        "text": "      if (typeof entry.probe !== \"string\" || !PROBE_COMMAND_NAMES.includes(entry.probe)) {"
      },
      {
        "number": 161,
        "text": "        unusable.push(`${at} 的 probe「${String(entry.probe)}」不在白名单（${PROBE_COMMAND_NAMES.join(\"｜\")}）`);"
      },
      {
        "number": 162,
        "text": "      } else if (entry.args === undefined) {"
      },
      {
        "number": 163,
        "text": "        unusable.push(`${at} 缺 args（白名单命令的参数形态：{${probeCommand(entry.probe).argKeys.join(\", \")}}）`);"
      },
      {
        "number": 164,
        "text": "      } else if (!isPlainObject(entry.args)) {"
      },
      {
        "number": 165,
        "text": "        unusable.push(`${at} 的 args 须为对象`);"
      },
      {
        "number": 166,
        "text": "      } else {"
      },
      {
        "number": 167,
        "text": "        // 参数键与白名单命令的 argKeys 精确一致（冻结期即按执行侧同口径校验——"
      },
      {
        "number": 168,
        "text": "        // 错形判据不得冻结成「永不满足」的死判据；参数值合法性在执行期判）。"
      },
      {
        "number": 169,
        "text": "        // 判定原语＝probe.js 的 argsMatchArgKeys（23 号票⑥：执行侧同口径单源，"
      },
      {
        "number": 170,
        "text": "        // 免两处各自实现可漂移）"
      },
      {
        "number": 171,
        "text": "        if (!argsMatchArgKeys(entry.args, probeCommand(entry.probe))) {"
      },
      {
        "number": 172,
        "text": "          unusable.push(`${at} 的 args 须恰为 {${probeCommand(entry.probe).argKeys.join(\", \")}}（逐字一致）`);"
      },
      {
        "number": 173,
        "text": "        }"
      },
      {
        "number": 174,
        "text": "      }"
      },
      {
        "number": 175,
        "text": "    });"
      },
      {
        "number": 176,
        "text": "    if (unusable.length > 0) {"
      },
      {
        "number": 177,
        "text": "      gap = { kind: \"criteria-gap\", reason: `验收判据不可执行（${unusable.length} 条）：${unusable.join(\"；\")}——先分解为可观测项，分解不出来标 needs-user 上浮` };"
      },
      {
        "number": 178,
        "text": "    }"
      },
      {
        "number": 179,
        "text": "  }"
      },
      {
        "number": 180,
        "text": ""
      },
      {
        "number": 181,
        "text": "  return { ok: violations.length === 0 && gap === null, violations, gap };"
      },
      {
        "number": 182,
        "text": "}"
      }
    ],
