      {
        "number": 381,
        "text": "/** 白名单名字集（封闭枚举的读面；简报校验与工具面派生共用）。 */"
      },
      {
        "number": 382,
        "text": "export const PROBE_COMMAND_NAMES = Object.freeze(PROBE_COMMANDS.map((command) => command.name));"
