        "text": " * - **复核帽**＝契约帽子：当次空闲实例佩戴（`selectReviewer`——台账无进行中"
      },
      {
        "number": 19,
        "text": " *   租约）、排除本任务产出方、无常驻席位（注册表腿：verifier 不在"
      },
      {
        "number": 20,
        "text": " *   STANDING_POST_SLUGS，归 role-cards 测试模块把守）。"
      },
      {
        "number": 21,
        "text": " */"
      },
      {
        "number": 22,
        "text": "import { isNonEmptyString } from \"./is-non-empty-string.js\";"
      },
      {
        "number": 23,
        "text": "import { isPlainObject } from \"./capability-base.js\";"
      },
      {
        "number": 24,
        "text": ""
      },
      {
        "number": 25,
        "text": "/** 必审清单（封闭枚举；三条客观判据＝三个边界事件，复核点在边界跨越之前）。 */"
      },
      {
        "number": 26,
        "text": "export const REVIEW_BOUNDARIES = Object.freeze(["
      },
      {
        "number": 27,
        "text": "  {"
      },
      {
        "number": 28,
        "text": "    id: \"before-irreversible-write\","
      },
      {
        "number": 29,
        "text": "    criterion: \"不可逆：写入真实运行面／冻结面、不可回滚的覆盖或删除\""
      },
      {
        "number": 30,
        "text": "  },"
      },
      {
        "number": 31,
        "text": "  {"
      },
      {
        "number": 32,
        "text": "    id: \"before-external-visibility\","
      },
      {
        "number": 33,
        "text": "    criterion: \"对外可见：交付用户、跨组织提交、外部 API 写入\""
      },
      {
        "number": 34,
        "text": "  },"
      },
      {
        "number": 35,
        "text": "  {"
      },
      {
        "number": 36,
        "text": "    id: \"before-cross-instance-handoff\","
      },
      {
        "number": 37,
        "text": "    criterion: \"跨实例移交的关键产出：下游任务输入工件、判据工件、组织常量变更\""
      },
      {
        "number": 38,
        "text": "  }"
      },
      {
        "number": 39,
        "text": "]);"
      },
      {
        "number": 40,
        "text": ""
      },
      {
        "number": 41,
        "text": "/** 边界 id 集（简报 reviewPoints 与复核请求的取值域）。 */"
      },
      {
        "number": 42,
        "text": "export const REVIEW_BOUNDARY_IDS = Object.freeze(REVIEW_BOUNDARIES.map((boundary) => boundary.id));"
      },
      {
        "number": 43,
        "text": ""
      },
      {
        "number": 44,
        "text": "/** gap 严重度取值域（封闭枚举）。 */"
      },
      {
        "number": 45,
        "text": "export const GAP_SEVERITIES = Object.freeze([\"blocker\", \"major\", \"minor\"]);"
      },
      {
        "number": 46,
        "text": ""
      },
      {
        "number": 47,
        "text": "/** 报告结论取值域：gaps-open＝有未闭合缺口；closed＝判据全过、无缺口。 */"
      },
      {
        "number": 48,
        "text": "export const REVIEW_VERDICTS = Object.freeze([\"gaps-open\", \"closed\"]);"
      },
      {
        "number": 49,
        "text": ""
      },
      {
        "number": 50,
        "text": "/**"
      },
      {
        "number": 51,
        "text": " * 「连续两轮未闭合即上浮」的轮数阈值（**单一源**：台账 `recordReviewReport` 的"
      },
      {
        "number": 52,
        "text": " * claim 侧与人间接口 `preScreenEscalation` 的初审判定都读它——阈值不得两处各写一份）。"
      },
      {
        "number": 53,
        "text": " */"
      },
      {
        "number": 54,
        "text": "export const UNCLOSED_ROUNDS_TO_ESCALATE = 2;"
      },
      {
        "number": 55,
        "text": ""
      },
      {
        "number": 56,
        "text": "export const REPORT_KEYS = Object.freeze([\"subject\", \"verdict\", \"gaps\", \"criteriaGaps\", \"modelIdentity\"]);"
      },
      {
        "number": 57,
        "text": "const GAP_KEYS = Object.freeze([\"severity\", \"summary\", \"evidence\"]);"
      },
      {
        "number": 58,
        "text": ""
      },
      {
        "number": 59,
        "text": "/**"
      },
      {
        "number": 60,
        "text": " * 复核报告形状校验（纯函数）。报告是复核者唯一可写产物：顶层键封闭（改工件／"
      },
      {
        "number": 61,
        "text": " * 改判据类字段无处安放）、gap 条目键封闭、严重度与结论取值封闭、verdict 与"
      },
      {
        "number": 62,
        "text": " * gaps 一致（closed 不得带 gaps、gaps-open 不得空列表）、模型身份必填。"
      },
      {
        "number": 63,
        "text": " */"
      },
      {
        "number": 64,
        "text": "export function validateReviewReport(report) {"
      },
      {
        "number": 65,
        "text": "  const violations = [];"
      },
      {
        "number": 66,
        "text": "  if (!isPlainObject(report)) {"
      },
      {
        "number": 67,
        "text": "    return { ok: false, violations: [\"复核报告须为对象（固定形状）\"] };"
      },
      {
        "number": 68,
        "text": "  }"
      },
      {
        "number": 69,
        "text": "  for (const key of Object.keys(report)) {"
      },
      {
        "number": 70,
        "text": "    if (!REPORT_KEYS.includes(key)) violations.push(`报告含未定义键 ${key}（复核者只读：报告不携带改工件／改判据字段）`);"
      },
      {
        "number": 71,
        "text": "  }"
      },
      {
        "number": 72,
        "text": "  if (!isNonEmptyString(report.subject)) violations.push(\"subject（复核对象：边界 id 或咨询主题）须为非空字符串\");"
      },
      {
        "number": 73,
        "text": "  if (!REVIEW_VERDICTS.includes(report.verdict)) {"
      },
      {
        "number": 74,
        "text": "    violations.push(`verdict 须为 ${REVIEW_VERDICTS.join(\"|\")} 之一：${String(report.verdict)}`);"
      },
      {
        "number": 75,
        "text": "  }"
      },
      {
        "number": 76,
        "text": "  if (!Array.isArray(report.gaps)) {"
      },
      {
        "number": 77,
        "text": "    violations.push(\"gaps 须为数组（可为空数组）\");"
      },
      {
        "number": 78,
        "text": "  } else {"
      },
      {
        "number": 79,
        "text": "    report.gaps.forEach((gap, index) => {"
      },
      {
        "number": 80,
        "text": "      const at = `gaps[${String(index)}]`;"
      },
      {
        "number": 81,
        "text": "      if (!isPlainObject(gap)) {"
      },
      {
        "number": 82,
        "text": "        violations.push(`${at} 须为 {severity, summary, evidence} 对象`);"
      },
      {
        "number": 83,
        "text": "        return;"
      },
      {
        "number": 84,
        "text": "      }"
      },
      {
        "number": 85,
        "text": "      for (const key of Object.keys(gap)) {"
      },
      {
        "number": 86,
        "text": "        if (!GAP_KEYS.includes(key)) violations.push(`${at} 含未定义键 ${key}（条目键封闭：${GAP_KEYS.join(\"/\")}）`);"
      },
      {
        "number": 87,
        "text": "      }"
      },
      {
        "number": 88,
        "text": "      if (!GAP_SEVERITIES.includes(gap.severity)) violations.push(`${at}.severity 须为 ${GAP_SEVERITIES.join(\"|\")} 之一`);"
      },
      {
        "number": 89,
        "text": "      if (!isNonEmptyString(gap.summary)) violations.push(`${at}.summary 须为非空字符串`);"
      },
      {
        "number": 90,
        "text": "      if (!isNonEmptyString(gap.evidence)) violations.push(`${at}.evidence（证据坐标）须为非空字符串`);"
      },
      {
        "number": 91,
        "text": "    });"
      },
      {
        "number": 92,
        "text": "  }"
      },
      {
        "number": 93,
        "text": "  if (report.verdict === \"closed\" && Array.isArray(report.gaps) && report.gaps.length > 0) {"
      },
      {
        "number": 94,
        "text": "    violations.push(\"verdict=closed 不得携带 gaps（结论与列表一致）\");"
      },
      {
        "number": 95,
        "text": "  }"
      },
      {
        "number": 96,
        "text": "  if (report.verdict === \"gaps-open\" && Array.isArray(report.gaps) && report.gaps.length === 0) {"
      },
      {
        "number": 97,
        "text": "    violations.push(\"verdict=gaps-open 须至少携带一条 gap（结论与列表一致）\");"
      },
      {
        "number": 98,
        "text": "  }"
      },
      {
        "number": 99,
        "text": "  if (report.criteriaGaps !== undefined) {"
      },
      {
        "number": 100,
        "text": "    if (!Array.isArray(report.criteriaGaps) || report.criteriaGaps.some((entry) => !isNonEmptyString(entry))) {"
      },
      {
        "number": 101,
        "text": "      violations.push(\"criteriaGaps（判据缺口）须为非空字符串数组（可为空数组）\");"
      },
      {
        "number": 102,
        "text": "    }"
      },
      {
        "number": 103,
        "text": "  }"
      },
      {
        "number": 104,
        "text": "  if (!isNonEmptyString(report.modelIdentity)) violations.push(\"modelIdentity（模型身份）须为非空字符串\");"
      },
      {
        "number": 105,
        "text": "  return { ok: violations.length === 0, violations };"
      },
      {
        "number": 106,
        "text": "}"
      },
      {
        "number": 107,
        "text": ""
      },
      {
        "number": 108,
        "text": "// ---------------- 状态折叠（无 stage 机：复核状态＝事件折叠的投影） ----------------"
      },
      {
        "number": 109,
        "text": ""
      },
      {
        "number": 110,
        "text": "/**"
      },
      {
        "number": 111,
        "text": " * 复核状态查询域（23 号票②）：`{brief, events, taskId}` 三件套在复核状态各查询"
      },
      {
        "number": 112,
        "text": " * （collectReviewState／openMandatorySubjects／human-inbox `preScreenBoundary`）的"
      },
      {
        "number": 113,
        "text": " * 共同入参形状——事件与简报在调用方一次读定后捆装传递，不再逐处散拼三键。"
      },
      {
        "number": 114,
        "text": " * 各查询函数照旧直接接受三键字面量（既有调用与断言面不动）。"
      },
      {
        "number": 115,
        "text": " */"
      },
      {
        "number": 116,
        "text": ""
      },
      {
        "number": 117,
        "text": "/** 复核状态查询域：冻结简报＋本任务事件＋任务 id 的具名捆装（三键透传）。 */"
      },
      {
        "number": 118,
        "text": "export function reviewScope({ brief, events, taskId } = {}) {"
      },
      {
        "number": 119,
        "text": "  return { brief, events, taskId };"
      },
      {
        "number": 120,
        "text": "}"
      },
      {
        "number": 121,
        "text": ""
      },
      {
        "number": 122,
        "text": "/** 台账任务投影 → 查询域（brief 取投影冻结件、taskId 取投影 id）。 */"
      },
      {
        "number": 123,
        "text": "export function taskReviewScope(task, events) {"
      },
      {
        "number": 124,
        "text": "  return { brief: task?.brief ?? null, events: events ?? [], taskId: task?.taskId };"
      },
      {
        "number": 125,
        "text": "}"
      },
      {
        "number": 126,
        "text": ""
      },
      {
        "number": 127,
        "text": "/**"
      },
      {
        "number": 128,
        "text": " * 复核事实事件分派表（23 号票①：collectReviewState 与 reviewHandoff 对同一事件"
      },
      {
        "number": 129,
        "text": " * 类型的 if 级联同型重复——subject 提取收拢为单一源，防两处口径漂移）。事件只经"
      },
      {
        "number": 130,
        "text": " * 台账命令面产生（point/topic 二选一、subject 必填在写路径已把守）。"
      },
      {
        "number": 131,
        "text": " */"
      },
      {
        "number": 132,
        "text": "const REVIEW_EVENT_DISPATCH = Object.freeze({"
      },
      {
        "number": 133,
        "text": "  \"review-requested\": (event) => event.point ?? event.topic,"
      },
      {
        "number": 134,
        "text": "  \"review-reported\": (event) => event.subject"
      },
      {
        "number": 135,
        "text": "});"
      },
      {
        "number": 136,
        "text": ""
      },
      {
        "number": 137,
        "text": "/**"
      },
      {
        "number": 138,
        "text": " * 本任务复核事实事件的共享单遍遍历：taskId 过滤 → 类型分派 → subject 守卫，然后"
      },
      {
        "number": 139,
        "text": " * 访问者按事件类型各自续处理。两种消费（折叠 vs 移交件行）共用同一条遍历。"
      },
      {
        "number": 140,
        "text": " */"
      },
      {
        "number": 141,
        "text": "function eachReviewEvent(events, taskId, visit) {"
      },
      {
        "number": 142,
        "text": "  for (const event of events ?? []) {"
      },
      {
        "number": 143,
        "text": "    if (taskId !== undefined && event?.taskId !== taskId) continue;"
      },
      {
        "number": 144,
        "text": "    const subjectOf = REVIEW_EVENT_DISPATCH[event?.type];"
      },
      {
        "number": 145,
        "text": "    if (subjectOf === undefined) continue;"
      },
      {
        "number": 146,
        "text": "    const subject = subjectOf(event);"
      },
      {
        "number": 147,
        "text": "    if (!isNonEmptyString(subject)) continue;"
      },
      {
        "number": 148,
        "text": "    visit(event, subject);"
      },
      {
        "number": 149,
        "text": "  }"
      },
      {
        "number": 150,
        "text": "}"
      },
      {
        "number": 151,
        "text": ""
      },
      {
        "number": 152,
        "text": "function emptySubject(key) {"
      },
      {
        "number": 153,
        "text": "  return {"
      },
      {
        "number": 154,
        "text": "    subject: key,"
      },
      {
        "number": 155,
        "text": "    mandatory: false,"
      },
      {
        "number": 156,
        "text": "    reviewer: null,"
      },
      {
        "number": 157,
        "text": "    rounds: 0,"
      },
      {
        "number": 158,
        "text": "    consecutiveUnclosed: 0,"
      },
      {
        "number": 159,
        "text": "    closed: false,"
      },
      {
        "number": 160,
        "text": "    reports: [],"
      },
      {
        "number": 161,
        "text": "    requests: 0"
      },
      {
        "number": 162,
        "text": "  };"
      },
      {
        "number": 163,
        "text": "}"
      },
      {
        "number": 164,
        "text": ""
      },
      {
        "number": 165,
        "text": "/**"
      },
      {
        "number": 166,
        "text": " * 复核状态折叠（纯函数）。输入＝冻结简报＋本任务事件序列；输出＝逐 subject"
      },
      {
        "number": 167,
        "text": " * （边界 id 或咨询主题）的 `{mandatory, reviewer, rounds, consecutiveUnclosed,"
      },
      {
        "number": 168,
        "text": " * closed, reports, requests}` 表。必审集＝`brief.reviewPoints`（派出即冻结，"
      },
      {
        "number": 169,
        "text": " * 无需请求事件）∪ 强制请求的 point——**命中即强制**的机械口径；咨询性请求"
      },
      {
        "number": 170,
        "text": " * （topic）不入必审集、永不阻断。`consecutiveUnclosed`＝trailing 连续"
      },
      {
        "number": 171,
        "text": " * gaps-open 报告数（「连续两轮未闭合」的计数原语）；`closed`＝最近一次报告"
      },
      {
        "number": 172,
        "text": " * 为 closed。"
      },
      {
        "number": 173,
        "text": " */"
      },
      {
        "number": 174,
        "text": "export function collectReviewState({ brief, events, taskId } = {}) {"
      },
      {
        "number": 175,
        "text": "  const subjects = new Map();"
      },
      {
        "number": 176,
        "text": "  function subjectFor(key) {"
      },
      {
        "number": 177,
        "text": "    let entry = subjects.get(key);"
      },
      {
        "number": 178,
        "text": "    if (entry === undefined) {"
      },
      {
        "number": 179,
        "text": "      entry = emptySubject(key);"
      },
      {
        "number": 180,
        "text": "      subjects.set(key, entry);"
      },
      {
        "number": 181,
        "text": "    }"
      },
      {
        "number": 182,
        "text": "    return entry;"
      },
      {
        "number": 183,
        "text": "  }"
      },
      {
        "number": 184,
        "text": "  const briefPoints = Array.isArray(brief?.reviewPoints) ? brief.reviewPoints : [];"
      },
      {
        "number": 185,
        "text": "  for (const point of briefPoints) {"
      },
      {
        "number": 186,
        "text": "    subjectFor(point).mandatory = true;"
      },
      {
        "number": 187,
        "text": "  }"
      },
      {
        "number": 188,
        "text": "  eachReviewEvent(events, taskId, (event, key) => {"
      },
      {
        "number": 189,
        "text": "    const entry = subjectFor(key);"
      },
      {
        "number": 190,
        "text": "    if (event.type === \"review-requested\") {"
      },
      {
        "number": 191,
        "text": "      entry.requests += 1;"
      },
      {
        "number": 192,
        "text": "      if (event.mandatory === true) entry.mandatory = true;"
      },
      {
        "number": 193,
        "text": "      if (isNonEmptyString(event.reviewer)) entry.reviewer = event.reviewer;"
      },
      {
        "number": 194,
        "text": "      return;"
      },
      {
        "number": 195,
        "text": "    }"
      },
      {
        "number": 196,
        "text": "    // review-reported：报告史追加＋trailing 连续未闭合计数"
      },
      {
        "number": 197,
        "text": "    entry.reports.push({"
      },
      {
        "number": 198,
        "text": "      verdict: event.verdict,"
      },
      {
        "number": 199,
        "text": "      gaps: event.gaps ?? [],"
      },
      {
        "number": 200,
        "text": "      criteriaGaps: event.criteriaGaps ?? [],"
      },
      {
        "number": 201,
        "text": "      modelIdentity: event.modelIdentity ?? null,"
      },
      {
        "number": 202,
        "text": "      reviewer: event.reviewer ?? null,"
      },
      {
        "number": 203,
        "text": "      seq: event.seq,"
      },
      {
        "number": 204,
        "text": "      at: event.at"
      },
      {
        "number": 205,
        "text": "    });"
      },
      {
        "number": 206,
        "text": "    entry.rounds += 1;"
      },
      {
        "number": 207,
        "text": "    if (event.verdict === \"gaps-open\") {"
      },
      {
        "number": 208,
        "text": "      entry.consecutiveUnclosed += 1;"
      },
      {
        "number": 209,
        "text": "      entry.closed = false;"
      },
      {
        "number": 210,
        "text": "    } else {"
      },
      {
        "number": 211,
        "text": "      entry.consecutiveUnclosed = 0;"
      },
      {
        "number": 212,
        "text": "      entry.closed = true;"
      },
      {
        "number": 213,
        "text": "    }"
      },
      {
        "number": 214,
        "text": "  });"
      },
      {
        "number": 215,
        "text": "  return { subjects };"
      },
      {
        "number": 216,
        "text": "}"
      },
      {
        "number": 217,
        "text": ""
      },
      {
        "number": 218,
        "text": "/**"
      },
      {
        "number": 219,
        "text": " * 必审开启集（`task.deliver` 拦截的判定原语，`V-A2.7`）：必审 subject 中"
      },
      {
        "number": 220,
        "text": " * 尚未闭合（未复核或最近报告 gaps-open）者。非空即不得交付／回笼。"
      },
      {
        "number": 221,
        "text": " */"
      },
      {
        "number": 222,
        "text": "export function openMandatorySubjects({ brief, events, taskId }) {"
      },
      {
        "number": 223,
