 * ＝零必审交付的既有口径一致。输入顺序保留，便于拒绝理由稳定可归因。
 */

/** 简报（或简报形对象）中的 reviewPoints → 保序、去重的 subject 集合数组。 */
export function reviewPointSubjects(brief) {
  if (!Array.isArray(brief?.reviewPoints)) return [];
  return [...new Set(brief.reviewPoints)];
}

