 * 加审不在结果中，置换件省略 reviewPoints 等价于删掉冻结件的全部 subject。
 */
export function droppedReviewPoints(previousBrief, nextBrief) {
  const previous = reviewPointSubjects(previousBrief);
  const next = new Set(reviewPointSubjects(nextBrief));
  return previous.filter((point) => !next.has(point));
}
`
