      verdict: event.verdict,
      gaps: event.gaps ?? [],
      criteriaGaps: event.criteriaGaps ?? [],
      modelIdentity: event.modelIdentity ?? null,
      reviewer: event.reviewer ?? null,
      seq: event.seq,
      at: event.at
