      {
        "number": 1,
        "text": "/**"
      },
      {
        "number": 2,
        "text": " * 复核点集合原语（org-v2 19 号票；规格 §C「可加审不可免审」）。"
      },
      {
        "number": 3,
        "text": " *"
      },
