      {
        "number": 7,
        "text": " *"
      },
      {
        "number": 8,
        "text": " * 本件只投影已通过简报形状门的字符串数组；非数组按空集处理，与省略 reviewPoints"
      },
      {
        "number": 9,
        "text": " * ＝零必审交付的既有口径一致。输入顺序保留，便于拒绝理由稳定可归因。"
      },
      {
        "number": 10,
        "text": " */"
      },
      {
        "number": 11,
        "text": ""
      },
      {
        "number": 12,
        "text": "/** 简报（或简报形对象）中的 reviewPoints → 保序、去重的 subject 集合数组。 */"
      },
      {
        "number": 13,
        "text": "export function reviewPointSubjects(brief) {"
      },
      {
        "number": 14,
        "text": "  if (!Array.isArray(brief?.reviewPoints)) return [];"
      },
      {
        "number": 15,
        "text": "  return [...new Set(brief.reviewPoints)];"
