{"description":"Lock review point set regression","code":"const brief = await tools.edit({
  file_path:'lib/org/brief.js',
  old_string:'export { droppedReviewPoints } from "./review-point-set.js";',
  new_string:'export { droppedReviewPoints };'
});
const tests = await tools.edit({
  file_path:'tests/org-brief.test.mjs',
  old_string:'  assert.deepEqual(droppedReviewPoints({ ...VALID_BRIEF }, { ...VALID_BRIEF }), [], "冻结件无点则无可删");\n  assert.deepEqual(droppedReviewPoints(undefined, { ...VALID_BRIEF }), [], "无冻结件（intake 前置换）不适用本判定");',
  new_string:'  assert.deepEqual(\n    droppedReviewPoints(\n      { ...VALID_BRIEF, reviewPoints: ["before-external-visibility", "before-external-visibility"] },\n      { ...VALID_BRIEF, reviewPoints: [] }\n    ),\n    ["before-external-visibility"],\n    "复核点按 subject 集合判定，重复冻结条目只报告一次删减"\n  );\n  assert.deepEqual(droppedReviewPoints({ ...VALID_BRIEF }, { ...VALID_BRIEF }), [], "冻结件无点则无可删");\n  assert.deepEqual(droppedReviewPoints(undefined, { ...VALID_BRIEF }), [], "无冻结件（intake 前置换）不适用本判定");'
});
return {brief,tests};"}

